export function Footer() {
    const year = new Date().getFullYear();

    return (
      <footer className="border-t border-border/20">
        <div className="max-w-2xl mx-auto px-6 py-10">
          <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
            <p className="text-[14px] text-muted-foreground/40">
              &copy; {year} Sabuj Ghosh
            </p>
            <p className="text-[14px] text-muted-foreground/40 italic">
              P.S. I don't write blogs.
            </p>
          </div>
        </div>
      </footer>
    );
  }

import { ProjectCard } from './ProjectCard';

const openSourceProjects = [
  {
    title: 'Sileo',
    description: 'An opinionated physics-based toast library for React.',
    href: 'https://github.com',
    badge: 'OSS',
    image: 'https://images.pexels.com/photos/1181676/pexels-photo-1181676.jpeg?auto=compress&cs=tinysrgb&w=96&h=96&dpr=1',
  },
  {
    title: 'Wora',
    description: 'A lossless audio player built for the modern web.',
    href: 'https://github.com',
    badge: 'OSS',
    image: 'https://images.pexels.com/photos/1105668/pexels-photo-1105668.jpeg?auto=compress&cs=tinysrgb&w=96&h=96&dpr=1',
  },
];

const brandProjects = [
  {
    title: 'Athletico',
    description: 'Athlete wellness and performance tracking platform.',
    href: 'https://example.com',
    image: 'https://images.pexels.com/photos/2662116/pexels-photo-2662116.jpeg?auto=compress&cs=tinysrgb&w=96&h=96&dpr=1',
  },
  {
    title: 'FLOTEK',
    description: 'HydroTech power solutions — brand identity and web experience.',
    href: 'https://example.com',
    image: 'https://images.pexels.com/photos/414837/pexels-photo-414837.jpeg?auto=compress&cs=tinysrgb&w=96&h=96&dpr=1',
  },
];

export function Projects() {
  return (
    <section className="pb-24 md:pb-32">
      <div className="max-w-2xl mx-auto px-6">
        <div className="space-y-14">
          <div>
            <h2 className="text-[13px] font-medium uppercase tracking-[0.1em] text-muted-foreground/50 mb-5">
              Open Source
            </h2>
            <div className="grid gap-2">
              {openSourceProjects.map((project) => (
                <ProjectCard key={project.title} {...project} />
              ))}
            </div>
          </div>

          <div>
            <h2 className="text-[13px] font-medium uppercase tracking-[0.1em] text-muted-foreground/50 mb-5">
              Brand Work
            </h2>
            <div className="grid gap-2">
              {brandProjects.map((project) => (
                <ProjectCard key={project.title} {...project} />
              ))}
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

