import { ArrowUpRight } from 'lucide-react';

interface ProjectCardProps {
  title: string;
  description: string;
  href: string;
  badge?: string;
  image?: string;
}

export function ProjectCard({ title, description, href, badge, image }: ProjectCardProps) {
  return (
    <a
      href={href}
      target="_blank"
      rel="noopener noreferrer"
      className="group block rounded-xl border border-border/30 bg-secondary/30 p-4 transition-all duration-200 hover:bg-secondary/60 hover:border-border/50"
    >
      <div className="flex items-center gap-4">
        {image && (
          <div className="flex-shrink-0 h-11 w-11 rounded-lg bg-background border border-border/30 flex items-center justify-center overflow-hidden">
            <img
              src={image}
              alt={title}
              className="h-6 w-6 object-cover rounded"
              loading="lazy"
            />
          </div>
        )}
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <h3 className="text-[15px] font-medium text-foreground">
              {title}
