import { useState } from 'react';
import { ArrowUpRight, ExternalLink, X } from 'lucide-react';
import {
  Drawer,
  DrawerContent,
  DrawerTitle,
} from '@/components/ui/drawer';

export type WorkItem = {
  title: string;
  description: string;
  href: string;
  image: string;
};

type Props = {
  items: WorkItem[];
};

export function WorkList({ items }: Props) {
  const [active, setActive] = useState<WorkItem | null>(null);

  return (
    <>
      <div className="grid gap-2">
        {items.map((item) => (
          <button
            key={item.title}
            type="button"
            onClick={() => setActive(item)}
            className="group block w-full rounded-lg p-3 -mx-3 text-left transition-colors duration-200 hover:bg-secondary/30"
          >
            <div className="flex items-center gap-3">
              <img
                src={item.image}
                alt={item.title}
                loading="lazy"
                className="shrink-0 h-7 w-7 object-contain rounded"
              />
              <div className="flex-1 min-w-0">
                <h3 className="text-[15px] font-medium text-foreground">
                  {item.title}
                </h3>
                <p className="mt-0.5 text-[14px] text-muted-foreground leading-relaxed">
                  {item.description}
                </p>
              </div>
              <ArrowUpRight className="h-4 w-4 shrink-0 text-muted-foreground/0 group-hover:text-muted-foreground transition-all duration-200 group-hover:translate-x-0.5 group-hover:-translate-y-0.5" />
            </div>
          </button>
        ))}
      </div>

      <Drawer open={active !== null} onOpenChange={(open) => !open && setActive(null)}>
        <DrawerContent className="h-[88vh] bg-background border-border/40">
          <DrawerTitle className="sr-only">
            {active ? `${active.title} preview` : 'Preview'}
          </DrawerTitle>

          <div className="flex items-center justify-between gap-3 px-4 py-3 border-b border-border/30">
            <div className="flex items-center gap-2.5 min-w-0">
              {active && (
                <img
                  src={active.image}
                  alt=""
                  className="h-5 w-5 shrink-0 object-contain rounded-sm"
                />
              )}
              <div className="min-w-0">
                <p className="text-[14px] font-medium text-foreground truncate">
                  {active?.title}
                </p>
                <p className="text-[12px] text-muted-foreground truncate">
                  {active?.href.replace(/^https?:\/\//, '')}
                </p>
              </div>
            </div>

            <div className="flex items-center gap-1">
              <a
                href={active?.href}
                target="_blank"
                rel="noopener noreferrer"
                aria-label="Open in new tab"
                className="inline-flex items-center justify-center h-8 w-8 rounded-md text-muted-foreground hover:text-foreground hover:bg-secondary transition-colors duration-200"
              >
                <ExternalLink className="h-[16px] w-[16px]" strokeWidth={1.8} />
              </a>
              <button
                type="button"
                onClick={() => setActive(null)}
                aria-label="Close"
                className="inline-flex items-center justify-center h-8 w-8 rounded-md text-muted-foreground hover:text-foreground hover:bg-secondary transition-colors duration-200"
              >
                <X className="h-[16px] w-[16px]" strokeWidth={1.8} />
              </button>
            </div>
          </div>

          <div className="relative flex-1 bg-muted/20">
            {active && (
              <iframe
                key={active.href}
                src={active.href}
                title={`${active.title} preview`}
                className="absolute inset-0 h-full w-full border-0"
                loading="lazy"
                referrerPolicy="no-referrer"
                sandbox="allow-scripts allow-same-origin allow-forms allow-popups"
              />
            )}
            <div className="pointer-events-none absolute inset-x-0 bottom-0 flex justify-center pb-3">
              <p className="pointer-events-auto text-[11px] text-muted-foreground/60 bg-background/70 backdrop-blur-sm px-2.5 py-1 rounded-full border border-border/30">
                If preview is blank the site blocks embedding —{' '}
                <a
                  href={active?.href}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="underline underline-offset-2 hover:text-foreground"
                >
                  open in new tab
                </a>
              </p>
            </div>
          </div>
        </DrawerContent>
      </Drawer>
    </>
  );
}

